'use strict';
const assert = require('node:assert/strict');
const {createHash} = require('node:crypto');
const fs = require('node:fs/promises');
const http = require('node:http');
const os = require('node:os');
const path = require('node:path');
const {chromium} = require(process.env.PLAYWRIGHT_PATH || 'playwright');

const root = process.cwd();
const dist = 'benchmarks/frameworks/dist/scale';
const rich = 'benchmarks/frameworks/rich';
const count = 1_000_000;
const arms = ['saba-baseline', 'saba-compiled', 'react'];
const offsets = Array.from({length:16}, (_, i) => (i + 1) * 8);
const rowPositions = [...offsets, ...offsets.slice(0, -1).reverse(), 0];
const rounds = Number(process.argv[2] || 9);
const destination = path.resolve(process.argv[3] || path.join(__dirname, 'scroll-overlap.json'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
assert.ok(Number.isInteger(rounds) && rounds > 0);
const wrapper = `
const mode = new URL(location.href).searchParams.get('mode');
const actual = await import('/actual-' + mode + '.js');
window.scrollReplacements = [];
export function mountScaleBand(host, records) {
  const band = actual.mountScaleBand(host, records);
  return {
    replace(records) {
      const t0 = performance.now();
      band.replace(records);
      const t1 = performance.now();
      window.scrollReplacements.push({first:records[0].id, end:records.at(-1).id + 1, ms:t1 - t0});
    },
    dispose: () => band.dispose(),
  };
}`;

async function measurePage(positions) {
  const assert = (valid, why) => { if (!valid) throw new Error(why); };
  const result = window.scale.start();
  assert(result.records === 1_000_000, 'Wrong model size');
  const viewport = document.querySelector('#viewport');
  const host = document.querySelector('#space .band');
  assert(viewport.clientHeight === 416, 'Unexpected viewport height');
  let previousNodes = new Map();
  let checkedIds = 0;
  function inspect(first, end) {
    assert(host.childElementCount === end - first, 'Incorrect window size');
    const nextNodes = new Map();
    let retained = 0;
    for (let i = 0; i < host.children.length; i++) {
      const node = host.children[i];
      const id = first + i;
      const score = (id * 37 + (id % 23) * 13) % 1000;
      assert(node.isConnected && Number(node.dataset.id) === id &&
        node.textContent === id + ' · ' + score, 'Wrong cell order or score for ' + id);
      if (previousNodes.has(id)) {
        assert(previousNodes.get(id) === node, 'Lost element identity on overlap for ' + id);
        retained++;
      }
      nextNodes.set(id, node);
      checkedIds++;
    }
    for (const [id, node] of previousNodes) {
      if (!nextNodes.has(id)) assert(!node.isConnected, 'Outgoing cell is still connected: ' + id);
    }
    previousNodes = nextNodes;
    return retained;
  }
  let stats = window.scale.windowStats();
  assert(stats.reconciles === 1 && stats.first === 0 && stats.end === 192, 'Unexpected initial band');
  assert(window.scrollReplacements.length === 0, 'Unexpected startup replacement');
  inspect(stats.first, stats.end);
  const steps = [];
  for (const topRow of positions) {
    const before = stats;
    const count = window.scrollReplacements.length;
    await new Promise(resolve => {
      viewport.addEventListener('scroll', resolve, {once:true});
      viewport.scrollTop = topRow * 26;
    });
    await new Promise(requestAnimationFrame);
    await new Promise(requestAnimationFrame);
    assert(viewport.scrollTop === topRow * 26, 'Missed scroll target');
    stats = window.scale.windowStats();
    assert(stats.first <= topRow * 8 && stats.end >= (topRow + 16) * 8, 'Uncovered viewport');
    const refills = window.scrollReplacements.length - count;
    // Every eight-row step consumes the buffer. At the very top the previous
    // window already covers the viewport and its trailing buffer.
    const expectedRefills = topRow === 0 ? 0 : 1;
    assert(refills === expectedRefills && stats.reconciles === before.reconciles + refills,
      'Unexpected refill count at row ' + topRow);
    if (refills) {
      assert(stats.first === Math.max(0, topRow - 8) * 8 && stats.end === (topRow + 24) * 8,
        'Unexpected window edges');
      const sample = window.scrollReplacements.at(-1);
      assert(sample.first === stats.first && sample.end === stats.end, 'Adapter received wrong window');
    }
    const retained = inspect(stats.first, stats.end);
    const overlap = Math.min(stats.end, before.end) - Math.max(stats.first, before.first);
    assert(retained === overlap && retained > 0, 'Missing overlap at row ' + topRow);
    steps.push({topRow, first:stats.first, end:stats.end, retained,
      replaceMs:refills ? window.scrollReplacements.at(-1).ms : null});
  }
  return {steps, checkedIds, refills:window.scrollReplacements.length,
    totalReplaceMs:window.scrollReplacements.reduce((total, sample) => total + sample.ms, 0)};
}

async function main() {
  const fileMap = {
    '/': rich + '/scale.html',
    '/scale.js': rich + '/scale.js',
    '/sliding-window.js': 'src/modules/sliding-window.js',
    '/actual-saba-baseline.js': path.join(__dirname, 'previous.js'),
    '/actual-saba-compiled.js': dist + '/saba-compiled.js',
    '/actual-react.js': dist + '/react.js',
  };
  const sha256 = {}, assets = new Map();
  for (const [url, file] of Object.entries(fileMap)) {
    const bytes = await fs.readFile(file);
    assets.set(url, bytes);
    sha256[url] = sha(bytes);
  }
  const build = JSON.parse(await fs.readFile(dist + '/manifest.json', 'utf8'));
  const prior = JSON.parse(await fs.readFile(path.join(__dirname, 'previous-manifest.json'), 'utf8'));
  for (const [file, expected] of Object.entries(build.sabaSourceSha256)) {
    assert.equal(sha(await fs.readFile(file)), expected, 'Stale production build ' + file);
  }
  assert.equal(sha256['/actual-saba-baseline.js'], prior.bundles['saba-compiled'].sha256);
  assert.equal(sha256['/actual-saba-compiled.js'], build.bundles['saba-compiled'].sha256);
  assert.equal(sha256['/actual-react.js'], build.bundles.react.sha256);
  for (const arm of arms) assets.set('/scale-' + arm + '.js', wrapper);
  const report = {
    metadata: {
      generatedAt:new Date().toISOString(), rounds, cpu:os.cpus()[0].model, os:os.type() + ' ' + os.release(),
      count, viewport:[1200,900], rowPositions, sha256, wrapperSha256:sha(wrapper), driverSha256:sha(await fs.readFile(__filename)),
      armBundles:Object.fromEntries(arms.map(arm => [arm,{file:fileMap['/actual-' + arm + '.js'],sha256:sha256['/actual-' + arm + '.js']}])),
      build, baselineBuild:prior, headless:process.env.SABA_HEADED !== '1', channel:'chromium',
      clock:'Sum of wall-clock elapsed milliseconds spent synchronously inside actual adapter.replace(records) over the trace. Excludes scroll dispatch, dataset initialization, slicing, correctness checks and paint. Fresh full Chromium process for each arm visit, rotating order.',
    },
    visits:[],
  };
  const server = http.createServer((req, res) => {
    const url = req.url.split('?')[0];
    if (!assets.has(url)) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, {'Content-Type':url === '/' ? 'text/html' : 'text/javascript', 'Cache-Control':'no-store'});
    res.end(assets.get(url));
  });
  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve); });
  const origin = 'http://127.0.0.1:' + server.address().port;
  let sharedGeometry;
  try {
    for (let round = 0; round < rounds; round++) {
      for (let slot = 0; slot < arms.length; slot++) {
        const arm = arms[(round + slot) % arms.length];
        const browser = await chromium.launch({
          channel:'chromium', headless:process.env.SABA_HEADED !== '1', executablePath:process.env.SABA_CHROME,
          args:['--renderer-process-limit=1','--js-flags=--max-old-space-size=768'],
        });
        try {
          const page = await browser.newPage({viewport:{width:1200,height:900}, serviceWorkers:'block'});
          const errors = [];
          page.on('pageerror', error => errors.push(error.message));
          await page.goto(origin + '/?scenario=buffered&count=' + count + '&mode=' + arm);
          await page.waitForFunction(() => Boolean(window.scale));
          let watchdog;
          let visit;
          try {
            visit = await Promise.race([
              page.evaluate(measurePage, rowPositions),
              new Promise((_, reject) => { watchdog = setTimeout(() => reject(new Error('Scroll visit timed out')), 30000); }),
            ]);
          } finally { clearTimeout(watchdog); }
          assert.deepEqual(errors, []);
          const geometry = visit.steps.map(({topRow, first, end, retained}) => [topRow, first, end, retained]);
          if (sharedGeometry) assert.deepEqual(geometry, sharedGeometry);
          else sharedGeometry = geometry;
          report.visits.push({...visit, arm, trial:round + 1, order:slot + 1, chromium:browser.version()});
          await fs.writeFile(destination + '.tmp', JSON.stringify(report, null, 2) + '\n');
          await fs.rename(destination + '.tmp', destination);
          console.log(round + 1, arm, visit.refills, visit.totalReplaceMs.toFixed(2));
        } finally { await browser.close(); }
      }
    }
  } finally { await new Promise(resolve => server.close(resolve)); }
}
main().catch(error => { console.error(error); process.exitCode = 1; });
